import{c as o,Q as l,j as g,m as u}from"./chunks/framework.DOi4mjdC.js";const q="/assets/bank%E7%BB%93%E6%9E%84%E7%A4%BA%E6%84%8F%E5%9B%BE%EF%BC%88%E5%9B%BE%E4%B8%AD%E7%AE%AD%E5%A4%B4%E6%96%B9%E5%90%91%E8%A1%A8%E7%A4%BA%E5%86%85%E5%AD%98%E6%8E%92%E5%B8%83%E7%9A%84%E9%A1%BA%E5%BA%8F%EF%BC%89-71.CKN_Wl8H.png",p="/assets/%E5%9C%B0%E5%9D%80%E5%88%86%E9%85%8D%E7%A4%BA%E6%84%8F%E5%9B%BE-72.h4f-qf4l.png",b=JSON.parse('{"title":"避免bank冲突（NPU架构版本3510）","description":"","frontmatter":{},"headers":[{"level":1,"title":"避免bank冲突（NPU架构版本3510）","slug":"避免bank冲突npu架构版本3510"},{"level":2,"title":"bank冲突的典型场景","slug":"bank冲突的典型场景"},{"level":2,"title":"如何避免bank冲突","slug":"如何避免bank冲突"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/内存访问/避免UB的bank冲突/避免bank冲突（NPU架构版本3510）.md","filePath":"guide/算子实践参考/SIMD算子性能优化/内存访问/避免UB的bank冲突/避免bank冲突（NPU架构版本3510）.md"}'),a={name:"guide/算子实践参考/SIMD算子性能优化/内存访问/避免UB的bank冲突/避免bank冲突（NPU架构版本3510）.md"};function r(d,t,s,e,n,i){return l(),g("div",null,[...t[0]||(t[0]=[u('<h1 id="避免bank冲突-npu架构版本3510" tabindex="-1">避免bank冲突（NPU架构版本3510） <a class="header-anchor" href="#避免bank冲突-npu架构版本3510" aria-label="Permalink to &quot;避免bank冲突（NPU架构版本3510）&quot;">​</a></h1><p>为了提高数据访问的效率和吞吐量，Unified Buffer采用了bank（大小相等的内存模块）结构设计。Unified Buffer总大小为256K，划分为16个bank。每个bank由512行组成，每行长度为32B。这16个bank进一步组织为8个bank group，每个bank group包含2个bank，例如bank7和bank15组成一个bank group。</p><p><strong>图 1</strong> bank结构示意图（图中箭头方向表示内存排布的顺序）<br><img src="'+q+'" alt="" title="bank结构示意图（图中箭头方向表示内存排布的顺序）-71"></p><p>每个bank可以独立地进行数据的读写操作，允许多个数据请求同时进行。然而，当多个读写操作试图同时访问同一个bank，由于硬件资源的限制，这些操作必须排队等待，会导致bank冲突，引起性能下降。</p><p>具体来说，Vector计算单元每拍（一个指令周期）能够从每个bank group中读取或写入一行数据。当多个读写操作试图同时访问同一个bank，Vector计算单元无法在同一个周期内处理所有请求，导致这些请求排队等待。这种排队增加了数据访问的延迟，降低了系统的整体性能。</p><h2 id="bank冲突的典型场景" tabindex="-1">bank冲突的典型场景 <a class="header-anchor" href="#bank冲突的典型场景" aria-label="Permalink to &quot;bank冲突的典型场景&quot;">​</a></h2><p>bank冲突主要可以分为以下三种场景：</p><ul><li><strong>读写冲突</strong>：读操作和写操作同时尝试访问同一个bank。</li><li><strong>写写冲突</strong>：多个写操作同时尝试访问同一个bank group。</li><li><strong>读读冲突</strong>：两个读操作同时尝试访问同一个bank，或者两个以上读操作同时尝试访问同一个bank group。</li></ul><p>下文给出了一些具体的示例，假设，0x10000地址在bank0上，0x10020在bank1上，如下图所示：</p><p><strong>图 2</strong> 地址分配示意图<br><img src="'+p+'" alt="" title="地址分配示意图-72"></p><ul><li><p>读写冲突示例</p><p>Vector指令的源操作数src和目的操作数dst同时读写到同一个bank时造成读写冲突，具体分析如下：</p><p><strong>表 1</strong> 读写冲突示例</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;5.9988002399520095%&quot;&gt;&lt;p&gt;序号&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.948010397920417%&quot;&gt;&lt;p&gt;src地址&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.507898420315936%&quot;&gt;&lt;p&gt;dst地址&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.51489702059588%&quot;&gt;&lt;p&gt;bank&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.36372725454909%&quot;&gt;&lt;p&gt;bank group&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;结论&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;5.9988002399520095%&quot;&gt;&lt;p&gt;示例1&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.948010397920417%&quot;&gt;&lt;p&gt;0x10020&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.507898420315936%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.51489702059588%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_id0 != &lt;/span&gt;&lt;span&gt;bank_id&lt;/span&gt;&lt;span&gt;1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.36372725454909%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_group_id0 != bank_group_id1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;src地址和dst地址分别属于bank0和bank1，故无冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;5.9988002399520095%&quot;&gt;&lt;p&gt;示例2&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.948010397920417%&quot;&gt;&lt;p&gt;0x10020&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.507898420315936%&quot;&gt;&lt;p&gt;0x10120&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.51489702059588%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_id0 &lt;/span&gt;&lt;span&gt;== &lt;/span&gt;&lt;span&gt;bank_id1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.36372725454909%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_group_id0 =&lt;/span&gt;&lt;span&gt;= &lt;/span&gt;&lt;span&gt;bank_group_id1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;src地址和dst地址的地址都在bank0，故存在冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>写写冲突示例</p><p>Vector指令目的操作数dst对应的8个DataBlock（block0-block7）同时写到一个bank group时造成写写冲突，具体分析如下：</p><p><strong>表 2</strong> 写写冲突示例</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;5.789726356216995%&quot;&gt;&lt;p&gt;序号&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;7.959673547767644%&quot;&gt;&lt;p&gt;dst地址&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.505520883341337%&quot;&gt;&lt;p&gt;blk_stride&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.660585693710996%&quot;&gt;&lt;p&gt;&lt;span&gt;block0_addr &lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.775804128660585%&quot;&gt;&lt;p&gt;&lt;span&gt;block1_addr &lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.967834853576573%&quot;&gt;&lt;p&gt;&lt;span&gt;block2_addr &lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.721075372059531%&quot;&gt;&lt;p&gt;...&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;43.61977916466635%&quot;&gt;&lt;p&gt;结论&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;5.789726356216995%&quot;&gt;&lt;p&gt;示例1&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;7.959673547767644%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.505520883341337%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.660585693710996%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.775804128660585%&quot;&gt;&lt;p&gt;0x10100&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.967834853576573%&quot;&gt;&lt;p&gt;0x10200&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.721075372059531%&quot;&gt;&lt;p&gt;...&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;43.61977916466635%&quot;&gt;&lt;p&gt;8个DataBlock均在一个bank group下，故全部冲突，8拍完成一个Repeat的写入。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>读读冲突</p><ul><li><p>Vector指令两个源操作数同时读到同一个bank时造成读读冲突，具体分析如下：</p><p><strong>表 3</strong> 双src场景读读冲突示例</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.5786842631473705%&quot;&gt;&lt;p&gt;序号&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;12.76744651069786%&quot;&gt;&lt;p&gt;src0地址&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.097180563887221%&quot;&gt;&lt;p&gt;src1地址&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.52629474105179%&quot;&gt;&lt;p&gt;bank&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.36372725454909%&quot;&gt;&lt;p&gt;bank group&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;结论&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.5786842631473705%&quot;&gt;&lt;p&gt;示例1&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;12.76744651069786%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.097180563887221%&quot;&gt;&lt;p&gt;0x10100&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.52629474105179%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_id0 == &lt;/span&gt;&lt;span&gt;bank_id&lt;/span&gt;&lt;span&gt;1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.36372725454909%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_group_id0 == bank_group_id1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;存在冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.5786842631473705%&quot;&gt;&lt;p&gt;示例2&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;12.76744651069786%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.097180563887221%&quot;&gt;&lt;p&gt;0x10020&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.52629474105179%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_id0 &lt;/span&gt;&lt;span&gt;!= &lt;/span&gt;&lt;span&gt;bank_id1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.36372725454909%&quot;&gt;&lt;p&gt;&lt;span&gt;bank_group_id0 !&lt;/span&gt;&lt;span&gt;= &lt;/span&gt;&lt;span&gt;bank_group_id1&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;无冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>Vector指令某一个源操作数对应的8个DataBlock(block0-block7）读到同一个bank时造成读读冲突，具体分析如下：</p><p><strong>表 4</strong> 单src场景读读冲突示例</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.117919521374119%&quot;&gt;&lt;p&gt;序号&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;11.560358969410403%&quot;&gt;&lt;p&gt;src地址&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.910257647399403%&quot;&gt;&lt;p&gt;blk_stride&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.798031458071987%&quot;&gt;&lt;p&gt;&lt;span&gt;block0_addr &lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.633986297404228%&quot;&gt;&lt;p&gt;&lt;span&gt;block1_addr &lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.234777574061564%&quot;&gt;&lt;p&gt;&lt;span&gt;block2_addr &lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.754800733378366%&quot;&gt;&lt;p&gt;...&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.98986779889993%&quot;&gt;&lt;p&gt;结论&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.117919521374119%&quot;&gt;&lt;p&gt;示例1&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;11.560358969410403%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.910257647399403%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.798031458071987%&quot;&gt;&lt;p&gt;0x10000&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.633986297404228%&quot;&gt;&lt;p&gt;0x10100&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;9.234777574061564%&quot;&gt;&lt;p&gt;0x10200&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.754800733378366%&quot;&gt;&lt;p&gt;...&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.98986779889993%&quot;&gt;&lt;p&gt;8个&lt;span&gt;DataBlock&lt;/span&gt;均在一个bank下，故全部冲突，8拍完成一个Repeat的读操作。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul></li></ul><h2 id="如何避免bank冲突" tabindex="-1">如何避免bank冲突 <a class="header-anchor" href="#如何避免bank冲突" aria-label="Permalink to &quot;如何避免bank冲突&quot;">​</a></h2><p>避免bank冲突的方法有两种：<strong>优化计算逻辑</strong>和<strong>优化地址分配</strong>。</p><ul><li><p><strong>优化计算逻辑</strong></p><p>对一个数据类型为float，shape为(16, 64)的输入每个元素加1。通过将计算逻辑由逐列计算改为逐行计算可避免同一Repeat下的冲突问题，实现方案对比如下：</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方案&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.6652389759564%&quot;&gt;&lt;p&gt;原始实现&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.520782634089365%&quot;&gt;&lt;p&gt;优化实现&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方法&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.6652389759564%&quot;&gt;&lt;p&gt;逐列计算，同一Repeat内输入的8个DataBlock都在同一个bank而发生读读冲突。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.520782634089365%&quot;&gt;&lt;p&gt;逐行计算，同一个Repeat内输入的8个DataBlock不在同一个bank内，避免了同一Repeat内的读读冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示意图&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.6652389759564%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../../figures/矩阵编程逻辑位置示意图-73.png&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.520782634089365%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../../figures/矩阵编程逻辑位置示意图-74.png&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示例代码&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.6652389759564%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;uint64_t mask = 64; AscendC::UnaryRepeatParams params; params.dstBlkStride = 8; params.srcBlkStride = 8; for(uint16_t i = 0; i &lt; 8; ++i){ AscendC::Adds(dst[i * 8], src[i * 8], 1, mask, 1, params); }&lt;/pre&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.520782634089365%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;uint64_t mask = 64; AscendC::UnaryRepeatParams params; params.dstBlkStride = 1; params.srcBlkStride = 1; for(uint16_t i = 0; i &lt; 8; ++i){ AscendC::Adds(dst[i * 64], src[i * 64], 1, mask, 1, params); }&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p><strong>优化地址分配</strong></p><p>实现连续4096个float元素的加法z = x + y，通过在内存分配时适当扩大内存，保证在一个Repeat内，x/y和z不会同时出现同一个bank内。</p><p>实现方案对比如下：</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方案&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.01304390148935%&quot;&gt;&lt;p&gt;原始实现&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.17297770855641%&quot;&gt;&lt;p&gt;优化实现&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方法&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.01304390148935%&quot;&gt;&lt;p&gt;不做地址优化，直接使用InitBuffer分配内存，各个Tensor的地址分别为：&lt;/p&gt; &lt;p&gt;x：起始地址0x00000，tensor长度为4096 * sizeof(float)字节&lt;/p&gt; &lt;p&gt;y：起始地址0x04000，tensor长度为4096 * sizeof(float)字节&lt;/p&gt; &lt;p&gt;z：起始地址0x08000，tensor长度为4096 * sizeof(float)字节&lt;/p&gt; &lt;p&gt;在一个Repeat内，x和y同时读同一个bank group，x/y和z同时读写同一个bank。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.17297770855641%&quot;&gt;&lt;p&gt;优化地址，使用InitBuffer分配内存时适当扩大内存申请，各个Tensor的地址分别为：&lt;/p&gt; &lt;p&gt;x：起始地址0x00000，tensor长度为4096 * sizeof(float) 字节&lt;/p&gt; &lt;p&gt;y：起始地址0x04000，tensor长度为(8 * 16 * 1024 - (4096 * sizeof(float) )字节&lt;/p&gt; &lt;p&gt;z：起始地址0x20000，tensor长度为4096 * sizeof(float) 字节&lt;/p&gt; &lt;p&gt;y多申请空间，确保z不会和x/y落入同一个bank。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示意图&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.01304390148935%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../../figures/矩阵编程逻辑位置示意图-75.png&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.17297770855641%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../../figures/矩阵编程逻辑位置示意图-76.png&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示例代码&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.01304390148935%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;pipe.InitBuffer(inQueueX, 1, 4096 * sizeof(float)); pipe.InitBuffer(inQueueY, 1, 4096 * sizeof(float)); pipe.InitBuffer(outQueueZ, 1, 4096 * sizeof(float));&lt;/pre&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.17297770855641%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;constexpr int32_t TOTAL_LENGTH = 1024 * 4; constexpr int32_t BUFFER_NUM = 1; constexpr int32_t BANKGROUP_SIZE = 1024 * 128; ... pipe.InitBuffer(inQueueX, BUFFER_NUM, TOTAL_LENGTH * sizeof(float)); pipe.InitBuffer(inQueueY, BUFFER_NUM, BANKGROUP_SIZE - TOTAL_LENGTH * sizeof(float)); pipe.InitBuffer(outQueueZ, BUFFER_NUM, TOTAL_LENGTH * sizeof(float));&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul>',14)])])}const h=o(a,[["render",r]]);export{b as __pageData,h as default};
